#[doc = r#"An enumeration representing varying "levels of effort"."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum AccessEffortEnum {
	#[doc = r#"Indicates maximum level of effort."#]
	#[serde(rename = "MAXIMUM_EFFORT")]
	MaximumEffort,
	#[doc = r#"Indicates the most likely level of effort."#]
	#[serde(rename = "MOST_LIKELY_EFFORT")]
	MostLikelyEffort,
	#[doc = r#"Indicates minimum level of effort."#]
	#[serde(rename = "MINIMUM_EFFORT")]
	MinimumEffort,
	#[doc = r#"Indicates zero level of effort."#]
	#[serde(rename = "ZERO_EFFORT")]
	ZeroEffort,
	#[doc = r#"Indicates a level of effort not categorized."#]
	#[serde(rename = "OTHER")]
	Other,
}

#[doc = r#"Indicates the level of achievability of an assessment.  See enumerated values for more details."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
