#[doc = r#"Indicates the basis of a reported Activity.  See enumerated type annotations for further details."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum ActivityBasisEnum {
	#[doc = r#"Indicates the activity is an actual one reported first-person or first-person surrogate."#]
	#[serde(rename = "ACTUAL")]
	Actual,
	#[doc = r#"Indicates the activity is a sensed, third-person activity reported by the sensor or sensor surrogate."#]
	#[serde(rename = "SENSED")]
	Sensed,
	#[doc = r#"Indicates the activity is a predicted, third-person activity reported by a prediction algorithm."#]
	#[serde(rename = "PREDICTED")]
	Predicted,
	#[doc = r#"Indicates the activity is a planned activity reported by an algorithm that estimates plan execution progress.  A PLANNED activity can be reported when an ACTUAL activity can't due to comms or other limitations."#]
	#[serde(rename = "PLANNED")]
	Planned,
}

#[doc = r#"Indicates the execution state of a planned Activity."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum ActivityExecutionStatusEnum {
	#[doc = r#"Indicates the associated Activity is pending execution."#]
	#[serde(rename = "PENDING")]
	Pending,
	#[doc = r#"Indicates the associated Activity is executing."#]
	#[serde(rename = "EXECUTING")]
	Executing,
	#[doc = r#"Indicates the Activity is paused."#]
	#[serde(rename = "PAUSED")]
	Paused,
	#[doc = r#"Indicates the Activity has completed and is no longer executing."#]
	#[serde(rename = "COMPLETED")]
	Completed,
	#[doc = r#"Indicates the Activity failed and is no longer executing."#]
	#[serde(rename = "FAILED")]
	Failed,
	#[doc = r#"Indicates the Activity was superseded by another Action."#]
	#[serde(rename = "SUPERCEDED")]
	Superceded,
	#[doc = r#"Indicates the Activity was canceled."#]
	#[serde(rename = "CANCELED")]
	Canceled,
}

