#[doc = r#"This enumerated type represents the state machine for an Activity.  Additional details including allowed transitions are given in the accompanying UML model for the Activity state machine."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum ActivityStateEnum {
	#[doc = r#"Indicates the Activity is disabled.  This is a default or commanded state.  A DISABLED Activity can't become ACTIVE_* unless it is first ENABLED via the associated [Capability]SettingsCommand."#]
	#[serde(rename = "DISABLED")]
	Disabled,
	#[doc = r#"Indicates the Activity is enabled.  This is a default or commanded state.  An ENABLED Activity is free to transition to ACTIVE_* and other states at the discretion of the host Subsystem."#]
	#[serde(rename = "ENABLED")]
	Enabled,
	#[doc = r#"Indicates the Activity is currently being performed and isn't performance limited by resource limitations or other constraints."#]
	#[serde(rename = "ACTIVE_UNCONSTRAINED")]
	ActiveUnconstrained,
	#[doc = r#"Indicates the Activity is currently being performed but performance is being limited by resource limitations or other constraints."#]
	#[serde(rename = "ACTIVE_PARTIALLY_CONSTRAINED")]
	ActivePartiallyConstrained,
	#[doc = r#"Indicates triggering conditions for the Activity currently exist but the Activity isn't being performed due to resource limitations or other constraints."#]
	#[serde(rename = "ACTIVE_FULLY_CONSTRAINED")]
	ActiveFullyConstrained,
	#[doc = r#"Indicates the Activity was ACTIVE_* and finished.  This is a termination state for the Activity state machine."#]
	#[serde(rename = "COMPLETED")]
	Completed,
	#[doc = r#"Indicates the Activity was ENABLED and was possibly ACTIVE_* but failed prior to being COMPLETED.  This is a termination state for the Activity state machine."#]
	#[serde(rename = "FAILED")]
	Failed,
	#[doc = r#"Indicates the Activity was deleted.  This is a termination state for the Activity state machine."#]
	#[serde(rename = "DELETED")]
	Deleted,
}

