#[doc = r#"Indicates the status of an engagement."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum ExternalCommandExecutionStateEnum {
	#[doc = r#"The entity is carrying out its mission or assignment."#]
	#[serde(rename = "EXECUTING")]
	Executing,
	#[doc = r#"The entity canceled the engagement."#]
	#[serde(rename = "CANCELED")]
	Canceled,
	#[doc = r#"The entity has completed its mission against the target and recommends another airborne strike operation (ASO) mission be conducted against the same target."#]
	#[serde(rename = "RECOMMEND_REATTACK")]
	RecommendReattack,
	#[doc = r#"Indicates preparation to engage or attack the target with an allocated weapon. Firing will not commence unless ordered or the target becomes eligible for destruction under existing doctrine and/or rules of engagement."#]
	#[serde(rename = "WEAPON_ASSIGNED")]
	WeaponAssigned,
	#[doc = r#"The entity's tracking radar is locked onto the target and ready to fire as soon as the target is within weapon range and the target is eligible for destruction."#]
	#[serde(rename = "LOCKED_ON")]
	LockedOn,
	#[doc = r#"The entity is currently attacking the target."#]
	#[serde(rename = "ENGAGING")]
	Engaging,
	#[doc = r#"A weapon has been launched against the target, and the weapon has not yet impacted or timed out."#]
	#[serde(rename = "WEAPON_RELEASED")]
	WeaponReleased,
	#[doc = r#"The target has been engaged by the destroyed and is no longer a threat. Any previously reported engagement is broken."#]
	#[serde(rename = "EFFECTIVE")]
	Effective,
	#[doc = r#"All targets have not been destroyed."#]
	#[serde(rename = "PARTIALLY_EFFECTIVE")]
	PartiallyEffective,
	#[doc = r#"Miss or abort; the target is not destroyed."#]
	#[serde(rename = "NOT_EFFECTIVE")]
	NotEffective,
	#[doc = r#"The entity is terminating the previously reported or ordered action against the target."#]
	#[serde(rename = "ENGAGEMENT_BROKEN")]
	EngagementBroken,
	#[doc = r#"The target constitutes a threat to friendly forces. The entity is unable to assure complete destruction of the target."#]
	#[serde(rename = "HEADS_UP")]
	HeadsUp,
	#[doc = r#"Interpreted as ENGAGEMENT_BROKEN by US systems."#]
	#[serde(rename = "ENGAGEMENT_INTERRUPTED")]
	EngagementInterrupted,
	#[doc = r#"This indicates the friendly is not yet tracking the target. The system will not fire on the target until ordered or the target becomes eligible for destruction under existing doctrine and/or rules of engagement."#]
	#[serde(rename = "INVESTIGATING")]
	Investigating,
	#[doc = r#"The friendly is maintaining surveillance on the target."#]
	#[serde(rename = "SHADOWING")]
	Shadowing,
	#[doc = r#"Then entity is taking action to divert the target from its intended flight path."#]
	#[serde(rename = "INTERVENING")]
	Intervening,
	#[doc = r#"The friendly is maintaining a position relative to a designated target from which a successful intercept can take effect if needed."#]
	#[serde(rename = "COVERING")]
	Covering,
	#[doc = r#"The friendly has completed its mission against the target and is reporting an unknown battle damage assessment (BDA)."#]
	#[serde(rename = "BDA_UNKNOWN")]
	BdaUnknown,
	#[doc = r#"The tasked target was not found."#]
	#[serde(rename = "TARGET_NOT_FOUND")]
	TargetNotFound,
	#[doc = r#"The task is an evaluation report."#]
	#[serde(rename = "EVALUATION_REPORT")]
	EvaluationReport,
}

