#[doc = r#"Contains the integration methods that are supported."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum IntegrationMethodEnum {
	#[doc = r#"A Runge-Kutta 4th-order integrator. Also known as RK4. No error control for the integration step size is included for this integrator. It is always fixed-step."#]
	#[serde(rename = "RUNGE_KUTTA_4")]
	RungeKutta4,
	#[doc = r#"A Runge-Kutta-Fehlberg adaptive-step, 7th-order integrator with 8th-order error control for integration step size. Also known as RKF78"#]
	#[serde(rename = "RUNGE_KUTTA_FEHLBERG_78")]
	RungeKuttaFehlberg78,
	#[doc = r#"A Runge-Kutta-Verner adaptive-step, 8th-order integrator with 9th-order error control for integration step size. Also known as RKV89"#]
	#[serde(rename = "RUNGE_KUTTA_VERNER_89")]
	RungeKuttaVerner89,
	#[doc = r#"A Bulirsch-Stoer adaptive-step integrator."#]
	#[serde(rename = "BULIRSCH_STOER")]
	BulirschStoer,
	#[doc = r#"A Gauss-Jackson integrator with no error control for integration step size."#]
	#[serde(rename = "GAUSS_JACKSON")]
	GaussJackson,
	#[doc = r#"A Prince-Dormand adaptive-step, 5th-order integrator with 4th-order error control for integration step size."#]
	#[serde(rename = "PRINCE_DORMAND_54")]
	PrinceDormand54,
	#[doc = r#"A Prince-Dormand adaptive-step, 8th-order integrator with 5th-order error control for integration step size that also includes a 3rd-order correction."#]
	#[serde(rename = "PRINCE_DORMAND_853")]
	PrinceDormand853,
	#[doc = r#"A Prince-Dormand adaptive-step, 8th-order integrator with 7th-order error control for integration step size."#]
	#[serde(rename = "PRINCE_DORMAND_87")]
	PrinceDormand87,
}

