#[serde(rename = "PO_CapabilityEnum")]
pub enum PoCapabilityEnum {
	#[doc = r#"Specifies that images are to be or have been collected."#]
	#[serde(rename = "SPOT_IMAGE")]
	SpotImage,
	#[doc = r#"This capability indicates that this payload has the ability to image an area on a surface, e.g. the surface of the earth."#]
	#[serde(rename = "AREA_IMAGE")]
	AreaImage,
	#[doc = r#"This capability indicates that this payload has the ability to sweep an area on a surface, e.g. the surface of the earth."#]
	#[serde(rename = "LINE_SWEEP")]
	LineSweep,
	#[doc = r#"Specifies that the sensor is capable to or has collected full motion video for a designated area."#]
	#[serde(rename = "FULL_MOTION_VIDEO")]
	FullMotionVideo,
	#[doc = r#"Specifies that a focus sweep is to be or has been performed."#]
	#[serde(rename = "FOCUS_SWEEP")]
	FocusSweep,
	#[doc = r#"This specific enumeration value provides additional information to the sensor indicating that the sensor has the ability to search a 3D area."#]
	#[serde(rename = "SEARCH_VOLUME")]
	SearchVolume,
	#[doc = r#"This specific enumeration value provides additional information to the sensor indicating that the sensor has the ability to search a 3D area around a cued location."#]
	#[serde(rename = "SEARCH_CUED")]
	SearchCued,
	#[doc = r#"This specific enumeration value provides additional information to the sensor indicating that the sensor has the ability to search a 3D area and can automatically pick out specific targets of interest."#]
	#[serde(rename = "SEARCH_ATR")]
	SearchAtr,
	#[doc = r#"This specific enumeration value provides additional information to the sensor indicating that the sensor has the ability to track a single target which it is given via a single cue or Entity."#]
	#[serde(rename = "TRACK_SINGLE")]
	TrackSingle,
	#[doc = r#"This specific enumeration value provides additional information to the sensor indicating that the sensor has the ability to track multiple targets which it is given via multiple cues or Entities."#]
	#[serde(rename = "TRACK_MULTI")]
	TrackMulti,
	#[doc = r#"Specifies that a calibration sweep is to be or has been performed."#]
	#[serde(rename = "CALIBRATE")]
	Calibrate,
	#[doc = r#"Specifies that a search for targets is to be performed using the collected image data."#]
	#[serde(rename = "SEARCH")]
	Search,
	#[doc = r#"Specifies that an identification for targets is to be performed using the collected image data."#]
	#[serde(rename = "TARGET_CLASSIFICATION")]
	TargetClassification,
	#[doc = r#"Specifies that a tracking of targets is to be performed using the collected image data."#]
	#[serde(rename = "TRACK")]
	Track,
	#[doc = r#"This capability indicates that this payload has the ability to cue itself to image some target. For example, if the payload was searching for a target or targets and found it, that payload might want to "automatically" take more images of the area where the target was found."#]
	#[serde(rename = "AUTO_CUE")]
	AutoCue,
	#[doc = r#"This capability indicates that this payload has the ability to revisit the same target for as long as the pitch range allows."#]
	#[serde(rename = "PERSISTENT_IMAGING")]
	PersistentImaging,
	#[doc = r#"This capability indicates that this payload has the ability to detect anomalies in the scene (e.g. in the terrain)."#]
	#[serde(rename = "ANOMALY_DETECTION")]
	AnomalyDetection,
	#[doc = r#"Indicates a Capability to measure and report a particular orbiting object's optical visual magnitude."#]
	#[serde(rename = "VISUAL_MAGNITUDE_MEASUREMENT")]
	VisualMagnitudeMeasurement,
	#[doc = r#"Indicates a Capability to identify the kind and/or instance of a particular orbiting object and report it in relation to a known catalog and/or space order of battle."#]
	#[serde(rename = "SOB_CORRELATION")]
	SobCorrelation,
}

#[doc = r#"The enumeration of all collection constraints that may apply to a Passive Optical sensor."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(rename = "PO_CollectionConstraintsEnum")]
pub enum PoCollectionConstraintsEnum {
	#[doc = r#"True Map Angle. The true map angle is defined in the Northeast Down (NED) coordinate system with the origin at the aircraft (aircraft local NED) as the angle between the scene entry line of sight and the instantaneous aircraft track heading vector. The aircraft track heading vector is obtained by rotating the north unit vector of the aircraft local NED coordinate system in the aircraft local NE plane through the aircraft track heading angle.  This angle is always positive."#]
	#[serde(rename = "MAP_ANGLE")]
	MapAngle,
	#[doc = r#"The angle at the target between the plane of the terrain and the line of sight to the sensor.  If the slope of the terrain is zero, this element is equivalent to the sibling ElevationAngleConstraints."#]
	#[serde(rename = "GRAZING_ANGLE")]
	GrazingAngle,
	#[doc = r#"The angle from true north to the line-of-sight vector from the sensor to the target tangent plane."#]
	#[serde(rename = "LOOKAHEAD_ANGLE")]
	LookaheadAngle,
	#[doc = r#"The angle at the target between the flat surface (ellipsoid surface ignoring terrain) and the line of sight to the sensor.  If the slope of the terrain is zero, this element is equivalent to the sibling GrazingAngleConstraints."#]
	#[serde(rename = "ELEVATION_ANGLE")]
	ElevationAngle,
	#[doc = r#"Distance from the sensor reference point (e.g. aperture reference point) to the ground reference point."#]
	#[serde(rename = "SLANT_RANGE")]
	SlantRange,
	#[doc = r#"This element defines the type of pattern that a vehicle should use to collect over a large area.  This can be specified when creating Tasks to collect over OpZones, ZoneTargets, Entities (which have been specified as zones), etc."#]
	#[serde(rename = "COLLECTION_PATTERN")]
	CollectionPattern,
	#[doc = r#"The angle from the target plane at intersection of the optical line of sight with the earth's surface at the time of the first image line."#]
	#[serde(rename = "SUN_ELEVATION")]
	SunElevation,
	#[doc = r#"The angle from True North clockwise (as viewed from space) at the time of the first image line."#]
	#[serde(rename = "SUN_AZIMUTH")]
	SunAzimuth,
	#[doc = r#"The rate at which the sensor look-point moves across the terrain.  This is only applicable to area or line targets."#]
	#[serde(rename = "SWEEP_SPEED")]
	SweepSpeed,
	#[doc = r#"The orientation of the gimbal with respect to its reference frame."#]
	#[serde(rename = "GIMBAL_ORIENTATION")]
	GimbalOrientation,
}

#[doc = r#"This enumeration provides additional environment information about the area of interest that the sensor is currently processing."#]
