	#[doc = r#"Indicates that the Chebyshev weighting function is used. The Chebyshev weighting function is used when reducing main lobe bandwidth is prioritized over reducing the magnitude of the sidelobes."#]
	#[serde(rename = "CHEBYSHEV")]
