#[doc = r#"Indicates whether the associated action should be performed once, periodically, or indicates that a periodic action should be stopped."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum RepeatEnum {
	#[doc = r#"Indicates the associated action should be performed only once."#]
	#[serde(rename = "SINGLE")]
	Single,
	#[doc = r#"Indicates the associated action should be performed periodically."#]
	#[serde(rename = "PERIODIC")]
	Periodic,
	#[doc = r#"Indicates the associated periodic action should be halted."#]
	#[serde(rename = "STOP")]
	Stop,
}

#[doc = r#"Indicates the processing status of a request."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum RequestProcessingStateEnum {
	#[doc = r#"Request has been received and accepted but is not yet processing."#]
	#[serde(rename = "QUEUED")]
	Queued,
	#[doc = r#"Request has been initiated and is still processing."#]
	#[serde(rename = "PROCESSING")]
	Processing,
	#[doc = r#"Request has successfully completed.  This is a terminal state of the processing status state machine."#]
	#[serde(rename = "COMPLETED")]
	Completed,
	#[doc = r#"Request failed to complete after initiation.  This is a terminal state of the processing status state machine."#]
	#[serde(rename = "FAILED")]
	Failed,
	#[doc = r#"Request was canceled by the requester prior to completion.  This is a terminal state of the processing status state machine."#]
	#[serde(rename = "CANCELED")]
	Canceled,
	#[doc = r#"Request was rejected by the recipient and will not be processed.  This is a terminal state of the processing status state machine."#]
	#[serde(rename = "REJECTED")]
	Rejected,
}

#[doc = r#"Enumeration listing the type of source sending an Entity Management Request."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum RequestSourceEnum {
	#[doc = r#"Request came from an operator on a system different from the handling service."#]
	#[serde(rename = "MANUAL_EXTERNAL")]
	ManualExternal,
	#[doc = r#"Request came from an operator that is part of the same system as the handling service."#]
	#[serde(rename = "MANUAL_INTERNAL")]
	ManualInternal,
	#[doc = r#"Request came from an automatic service on a system different from the handling service."#]
	#[serde(rename = "AUTOMATIC_EXTERNAL")]
	AutomaticExternal,
	#[doc = r#"Request came from an automatic service that is part of the same system as the handling service."#]
	#[serde(rename = "AUTOMATIC_INTERNAL")]
	AutomaticInternal,
}

#[doc = r#"Indicates whether an instance of a request message is new, an update to an existing message or a request to cancel the message."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum RequestStateEnum {
	#[doc = r#"Indicates that the request message is new to the network."#]
	#[serde(rename = "NEW")]
	New,
	#[doc = r#"Indicates that this request message is an update to a request message previously placed on the network."#]
	#[serde(rename = "UPDATE")]
	Update,
	#[doc = r#"Indicates that the request should be canceled."#]
	#[serde(rename = "CANCEL")]
	Cancel,
}

#[doc = r#"Indicates a kind of temporal dependency between Requirements."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum RequirementDependencyEnum {
	#[doc = r#"Indicates a temporal dependency where a Requirement starts relative to the finish of a reference Requirement."#]
	#[serde(rename = "FINISH_TO_START")]
	FinishToStart,
	#[doc = r#"Indicates a temporal dependency where a Requirement starts relative to the start of a reference Requirement."#]
	#[serde(rename = "START_TO_START")]
	StartToStart,
	#[doc = r#"Indicates a temporal dependency where a Requirement finishes relative to the finish of a reference Requirement."#]
	#[serde(rename = "FINISH_TO_FINISH")]
	FinishToFinish,
	#[doc = r#"Indicates a temporal dependency where a Requirement finishes relative to the start of a reference Requirement."#]
	#[serde(rename = "START_TO_FINISH")]
	StartToFinish,
}

#[doc = r#"Indicates the execution state of a Requirement (Effect, Action, Task, etc.)."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum RequirementExecutionStateEnum {
	#[doc = r#"The Requirement is awaiting activation of the associated Plan."#]
	#[serde(rename = "AWAITING_PLAN_ACTIVATION")]
	AwaitingPlanActivation,
	#[doc = r#"Awaiting execution approval of the Requirement."#]
	#[serde(rename = "AWAITING_EXECUTION_APPROVAL")]
	AwaitingExecutionApproval,
	#[doc = r#"The Requirement has been approved for execution and the associated plans have been activated, the Requirement has not yet executed (i.e. time to execution &gt; 0)."#]
	#[serde(rename = "EXECUTION_PENDING")]
	ExecutionPending,
	#[doc = r#"The System begins execution of a Requirement,  For example, the System slews sensor and begins collection, begins to prepare weapons for release, starts jamming, etc.).  Once a Requirement transitions to this state, it can no longer be reallocated to another System, unless it transitions to the FAILED state."#]
	#[serde(rename = "EXECUTING")]
	Executing,
	#[doc = r#"Collection Requirements are considered complete when the resulting product is processed and disseminated.  All other Requirements are complete once the System transitions from the executing state after completing the Requirement as commanded/planned (vehicle releases weapon, stops jamming, etc.)."#]
	#[serde(rename = "COMPLETED")]
	Completed,
	#[doc = r#"A Requirement has been dropped by a System and is subject for reallocation within the same System node before escalation to a higher node for reallocation."#]
	#[serde(rename = "DROPPED")]
	Dropped,
	#[doc = r#"The System node has determined that it cannot achieve the task.  The FAILED state escalates the issue for reallocation across Systems."#]
	#[serde(rename = "FAILED")]
	Failed,
	#[doc = r#"Indicates the Requirement has been canceled and will not be executed."#]
	#[serde(rename = "CANCELED")]
	Canceled,
}

#[doc = r#"Indicates a Requirement-related object/actor."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum RequirementObjectEnum {
	#[doc = r#"Indicates the object/System which the Requirement is allocated to."#]
	#[serde(rename = "ALLOCATED_SYSTEM")]
	AllocatedSystem,
	#[doc = r#"Indicates the object that is the target of the Requirement.  The term "target" is used in a general sense.  For some Requirement types, a more suitable term might be "subject", "point", "location", etc.  For example, the "target" of a SUPPORT Effect could be a blue/friendly System."#]
	#[serde(rename = "TARGET_OBJECT")]
	TargetObject,
	#[doc = r#"Indicates the secondary object for the Requirement.  Some Requirements are constrained by target object behavior on or relative to another battlespace object, the secondary object.  For example, an Electronic Attack Task can be a "three object/body problem"; the blue jammer is the ALLOCATED_SYSTEM, the red radar site is the TARGET_OBJECT and the blue protected asset is the SECONDARY_OBJECT."#]
	#[serde(rename = "SECONDARY_OBJECT")]
	SecondaryObject,
	#[doc = r#"Indicates all objects related to a Requirement."#]
	#[serde(rename = "ALL")]
	All,
}

#[doc = r#"Indicates the planning state of a Requirement (Effect, Action, Task, etc.)."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum RequirementPlanningStateEnum {
	#[doc = r#"A Requirement that is not allocated to any System.  The Requirement is either newly created, was not able to be allocated, or was previously allocated then DROPPED or FAILED during execution."#]
	#[serde(rename = "UNALLOCATED")]
	Unallocated,
	#[doc = r#"A Requirement that has been proposed to an allocation service and is not currently allocated to any other System."#]
	#[serde(rename = "PROPOSED")]
	Proposed,
	#[doc = r#"A Requirement that has been allocated to a System (or multiple Systems) in a *Plan but not yet planned in any *ActionPlan.  In this state, additional details of allocation results are expected in other planning status elements and associated *Plan."#]
	#[serde(rename = "ALLOCATED")]
	Allocated,
	#[doc = r#"A Requirement that has been planned in an *ActionPlan (or multiple *ActionPlans).    In this state, additional details are expected in other planning status elements."#]
	#[serde(rename = "PLANNED")]
	Planned,
	#[doc = r#"Indicates the Requirement has been canceled, and will not be allocated, planned, or executed."#]
	#[serde(rename = "CANCELED")]
	Canceled,
}

