#[doc = r#"Indicates different techniques/methods to measure the Line of Sight (LOS) of an RF signal."#]
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub enum SignalMeasurementMethodEnum {
	#[doc = r#"A method where the LOS Measurement is estimated based on amplitude comparison between two intersecting antenna patterns."#]
	#[serde(rename = "AMPLITUDE")]
	Amplitude,
	#[doc = r#"A method where ambiguous interferometer angle of arrival measurement, is resolved into the LOS Measurement using amplitude comparison."#]
	#[serde(rename = "AMPLITUDE_RESOLVED_PHASE")]
	AmplitudeResolvedPhase,
	#[doc = r#"A method where unambiguous (in angle) interferometer angle of arrival measurements are resolved across multiple, simultaneous short baseline interferometer (SBI) baselines.   SBI provides the LOS measurement after cone-correction of elevation angle."#]
	#[serde(rename = "SBI")]
	Sbi,
	#[doc = r#"A method where highly ambiguous (in angle) interferometer angle of arrival measurements are resolved over time into the LOS measurement."#]
	#[serde(rename = "LBI")]
	Lbi,
	#[doc = r#"A method where the LOS measurement is derived from Geolocation estimate of location."#]
	#[serde(rename = "GEO_CALCULATED")]
	GeoCalculated,
	#[doc = r#"A method where LOS is measured using radar (active) sum and difference Direction of Arrival measurement."#]
	#[serde(rename = "MONOPULSE")]
	Monopulse,
	#[doc = r#"A method where LOS is measured via another unspecified means which has not yet been incorporated into UCI."#]
	#[serde(rename = "OTHER")]
	Other,
	#[doc = r#"A method where LOS is measured using dual simultaneous short baseline interferometer (SBI) baselines."#]
	#[serde(rename = "DUAL_SBI")]
	DualSbi,
	#[doc = r#"A method where LOS is measured using amplitude comparison direction finding (ACDF)."#]
	#[serde(rename = "ACDF")]
	Acdf,
	#[doc = r#"A method where LOS is measured using both simultaneous short baseline interferometer (SBI) and amplitude comparison direction finding (ACDF)."#]
	#[serde(rename = "ACDF_SBI")]
	AcdfSbi,
}

